CREATE TABLE "behavior_incident" ("incident_id" INT PRIMARY KEY, "student_id" INT, "incident_type_code" TEXT(10), "date_incident_start" TIMESTAMP, "date_incident_end" TIMESTAMP, "incident_summary" TEXT(255), "recommendations" TEXT(255), "other_details" TEXT(255), FOREIGN KEY ("student_id") REFERENCES "students" ("student_id"), FOREIGN KEY ("incident_type_code") REFERENCES "ref_incident_type" ("incident_type_code"));
CREATE TABLE "detention" ("detention_id" INT PRIMARY KEY, "teacher_id" INT, "detention_type_code" TEXT(10), "datetime_detention_start" TIMESTAMP, "datetime_detention_end" TIMESTAMP, "detention_summary" TEXT(255), "other_details" TEXT(255), FOREIGN KEY ("teacher_id") REFERENCES "teachers" ("teacher_id"), FOREIGN KEY ("detention_type_code") REFERENCES "ref_detention_type" ("detention_type_code"));
CREATE TABLE "student_addresses" ("student_id" INT, "address_id" INT, "date_address_from" TIMESTAMP, "date_address_to" TIMESTAMP, "monthly_rental" FLOAT(19, 4), "other_details" TEXT(255), FOREIGN KEY ("student_id") REFERENCES "students" ("student_id"), FOREIGN KEY ("address_id") REFERENCES "addresses" ("address_id"));
CREATE TABLE "students_in_detention" ("student_id" INT, "detention_id" INT, "incident_id" INT, FOREIGN KEY ("student_id") REFERENCES "students" ("student_id"), FOREIGN KEY ("detention_id") REFERENCES "detention" ("detention_id"), FOREIGN KEY ("incident_id") REFERENCES "behavior_incident" ("incident_id"));

